import re, random, statistics
from collections import Counter, defaultdict
# Read the actual file
with open('region.fasta') as f:
    content=f.read()
lines=content.splitlines()
header=lines[0]
seq=''.join(l.strip() for l in lines[1:] if not l.startswith('>'))
print('header',header)
print('length',len(seq))
print('base counts',Counter(seq))
gc=(seq.count('G')+seq.count('C'))/len(seq)
print('GC %.4f'%gc)
L=len(seq)
comp=str.maketrans('ACGT','TGCA')
rc=seq.translate(comp)[::-1]
stops={'TAA','TAG','TGA'}
starts_all={'ATG','GTG','TTG'}
bases='TCAG'
aas='FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG'
codon_table={}
k=0
for a in bases:
    for b in bases:
        for c in bases:
            codon_table[a+b+c]=aas[k]; k+=1
def translate(s):
    return ''.join(codon_table.get(s[i:i+3],'X') for i in range(0,len(s)-2,3))
def map_coords(strand,start,end):
    if strand=='+': return start+1, end
    else: return L-end+1, L-start
# ORFs with all start codons
orfs=[]
for strand,s in [('+',seq),('-',rc)]:
    for frame in range(3):
        i=frame; start=None
        while i+3<=len(s):
            cod=s[i:i+3]
            if cod in starts_all and start is None:
                start=i
            if cod in stops and start is not None:
                coords=map_coords(strand,start,i+3)
                prot=translate(s[start:i+3])
                orfs.append((len(prot),strand,coords[0],coords[1],s[start],prot,s[start:i+3]))
                start=None
            i+=3
print('\nLongest ORFs (all start codons):')
for o in sorted(orfs, reverse=True)[:10]:
    print('aa=%d strand=%s %d-%d start=%s'% (o[0],o[1],o[2],o[3],o[4]))
    print('prot:',o[5])
    print('dna :',o[6])
    print()
# ORFs with ATG only
orfs_atg=[]
for strand,s in [('+',seq),('-',rc)]:
    for frame in range(3):
        i=frame; start=None
        while i+3<=len(s):
            cod=s[i:i+3]
            if cod=='ATG' and start is None:
                start=i
            if cod in stops and start is not None:
                coords=map_coords(strand,start,i+3)
                prot=translate(s[start:i+3])
                orfs_atg.append((len(prot),strand,coords[0],coords[1],prot,s[start:i+3]))
                start=None
            i+=3
print('Longest ATG-only ORFs:')
for o in sorted(orfs_atg, reverse=True)[:5]:
    print('aa=%d strand=%s %d-%d'% (o[0],o[1],o[2],o[3]))
    print(o[4])
    print()
# longest stop-free regions
best_sf=(0,None)
for strand,s in [('+',seq),('-',rc)]:
    for frame in range(3):
        i=frame; cur=frame
        while i+3<=len(s):
            if s[i:i+3] in stops:
                n=(i-cur)//3
                if n>best_sf[0]:
                    best_sf=(n,(strand,map_coords(strand,cur,i),cur,i,s[cur:i]))
                cur=i+3
            i+=3
        n=(len(s)-cur)//3
        if n>best_sf[0]:
            best_sf=(n,(strand,map_coords(strand,cur,len(s)),cur,len(s),s[cur:]))
print('Longest stop-free region:',best_sf[0],'codons',best_sf[1][0],best_sf[1][1])
print('Sequence:',best_sf[1][4])
print()
# exact repeats non-overlapping length >=8
print('Exact non-overlapping repeats length >=8:')
seen=set()
for length in range(20,7,-1):
    d={}
    for i in range(L-length+1):
        sub=seq[i:i+length]
        if sub in d:
            j=d[sub]
            if i-j>=length:
                key=(length,j+1,i+1,sub)
                if key not in seen:
                    seen.add(key)
                    print(key)
                break
        else:
            d[sub]=i
# inverted repeats arms >=8
print('\nInverted repeats arms >=8 (non-overlapping):')
inv=[]
for length in range(20,7,-1):
    d={}
    for i in range(L-length+1):
        sub=seq[i:i+length]
        d.setdefault(sub,[]).append(i)
    for i in range(L-length+1):
        sub=seq[i:i+length]
        rcm=sub.translate(comp)[::-1]
        for j in d.get(rcm,[]):
            if j>i+length:
                inv.append((length,i+1,j+1,sub))
                break
        else:
            continue
        break
# dedupe
s=sorted(set(inv), key=lambda x:(-x[0],x[1]))
for x in s[:20]: print(x)
# motifs
print('\nSelected motifs:')
for mo in ['TTGACA','TATAAT','TATA','CAAT','GGAGG','AGGAGG','GATCT','GATC','TTTTTT','AATAAA','GAATTC','AAGCTT','GGATCC','CTCGAG','TCTAGA','GCTAGC','GTTTAAAC']:
    hits=[m.start()+1 for m in re.finditer('(?='+mo+')',seq)]
    print(mo, len(hits), hits[:20])
# Monte Carlo p-values for longest ORF and stopfree
def longest_orf_aa(s):
    r=s.translate(comp)[::-1]
    best=0
    for ss in [s,r]:
        for frame in range(3):
            start=None; i=frame
            while i+3<=len(ss):
                cod=ss[i:i+3]
                if cod in starts_all and start is None: start=i
                if cod in stops:
                    if start is not None:
                        aa=(i+3-start)//3
                        if aa>best: best=aa
                    start=None
                i+=3
    return best
def longest_sf(s):
    r=s.translate(comp)[::-1]
    best=0
    for ss in [s,r]:
        for frame in range(3):
            cur=frame; i=frame
            while i+3<=len(ss):
                if ss[i:i+3] in stops:
                    n=(i-cur)//3
                    if n>best: best=n
                    cur=i+3
                i+=3
            n=(len(ss)-cur)//3
            if n>best: best=n
    return best
obs_orf=longest_orf_aa(seq)
obs_sf=longest_sf(seq)
random.seed(42)
sims_orf=[]; sims_sf=[]
for _ in range(1000):
    s=''.join(random.choice(seq) for _ in range(L))
    sims_orf.append(longest_orf_aa(s))
    sims_sf.append(longest_sf(s))
print('\nMonte Carlo (iid same composition, 1000 reps):')
print('longest ORF obs',obs_orf,'sim mean %.1f sd %.1f p>=obs %.3f'%(statistics.mean(sims_orf),statistics.stdev(sims_orf),sum(1 for x in sims_orf if x>=obs_orf)/len(sims_orf)))
print('longest stopfree obs',obs_sf,'sim mean %.1f sd %.1f p>=obs %.3f'%(statistics.mean(sims_sf),statistics.stdev(sims_sf),sum(1 for x in sims_sf if x>=obs_sf)/len(sims_sf)))
# GC skew
sk=[(1 if b=='G' else 0)-(1 if b=='C' else 0) for b in seq]
cum=[]; c=0
for v in sk:
    c+=v; cum.append(c)
print('\nGC skew cumulative min/max',min(cum),max(cum),'range',max(cum)-min(cum))
